  console.log('\n--- MÓDULO CROSS-REFS ---');

  await runTest('FUNC-031', 'Referências cruzadas (GET /cross-refs?ref=John%203:16)', 'bíblia', async () => {
    const res = await fetchJson('/api/v1/cross-refs?ref=John%203:16');
    const refs = res.data?.data || res.data || [];
    const passed = res.status === 200 && (Array.isArray(refs) ? refs.length > 0 : res.data?.count > 0);
    return {
      passed,
      evidence: `HTTP ${res.status}, referências encontradas: ${Array.isArray(refs) ? refs.length : res.data?.count || 0}`,
    };
  });

  // ─── IA / RAG (🔴 Crítico) ──────────────────────────────────────────────────
  console.log('\n--- MÓDULO IA / RAG ---');

  await runTest('FUNC-071', 'Estatísticas RAG (GET /rag/stats)', 'ia', async () => {
    const res = await fetchJson('/api/v1/rag/stats');
    const data = res.data?.data || res.data;
    const passed = res.status === 200 && data !== undefined;
    return {
      passed,
      evidence: `HTTP ${res.status}, stats: ${JSON.stringify(data)}`,
    };
  });

  await runTest('FUNC-075', 'Chat IA RAG (POST /rag/chat)', 'ia', async () => {
    const started = Date.now();
    const res = await fetchJson('/api/v1/rag/chat', {
      method: 'POST',
      timeout: 60000, // Gemini pode levar 10-25s
      body: JSON.stringify({
        message: 'O que é graça sob a perspectiva bíblica?',
        userId: 'qa-test',
      }),
    });
    const dur = Date.now() - started;
    const reply = res.data?.response || res.data?.data?.response || res.data?.reply || res.data?.message || '';
    const hasLength = typeof reply === 'string' && reply.length > 50;
    const isTruncated = reply.endsWith('...') || reply.endsWith('..');
    const passed = res.status === 200 && hasLength;
    return {
      passed,
      evidence: `HTTP ${res.status} em ${dur}ms. Caracteres: ${reply.length}. Truncado: ${isTruncated ? 'SIM' : 'NÃO'}. Início: "${reply.slice(0, 80)}..."`,
      details: { replyLength: reply.length, isTruncated, fullReply: reply },
    };
  });

  // ─── ACERVO / DRIVE (🔴 Crítico) ───────────────────────────────────────────
  console.log('\n--- MÓDULO ACERVO / DRIVE ---');

  await runTest('FUNC-094', 'Verificação da rota de Ingestão do Drive (POST /drive-library/ingest)', 'acervo', async () => {
    const res = await fetchJson('/api/v1/drive-library/ingest', {
      method: 'POST',
      body: JSON.stringify({ folderId: '', tradition: 'Geral' }),
    });
    // Rota protegida por JWT ou sem folderId -> se responder 401 ou 400, a rota EXISTE (não é 404).
    const passed = res.status !== 404;
    return {
      passed,
      evidence: `HTTP ${res.status} (não é 404) - Rota /api/v1/drive-library/ingest está mapeada e ativa`,
    };
  });

  // ─── RESUMO ────────────────────────────────────────────────────────────────
  console.log('\n======================================================');
  console.log('RESUMO FINAL DE EXECUÇÃO:');
  const total = results.length;
  const passedCount = results.filter((r) => r.passed).length;
  const failedCount = total - passedCount;
  const score = ((passedCount / total) * 100).toFixed(1);

  console.log(`Total de testes: ${total}`);
  console.log(`Aprovados:       ${passedCount}`);
  console.log(`Falhas:          ${failedCount}`);
  console.log(`Health Score:    ${score}%\n`);

  process.stdout.write(JSON.stringify({ total, passedCount, failedCount, score, results }, null, 2));
}

main().catch((err) => {
  console.error('Erro fatal:', err);
  process.exit(1);
});

